CREATE COLUMN TABLE "TEST_AP"."MSN4" ("AbsEntry" INTEGER CS_INT NOT NULL , "ItemCode" NVARCHAR(50) NOT NULL , "Selected" NVARCHAR(1) DEFAULT 'Y', "TmpForMrp" NVARCHAR(1) DEFAULT 'N', "WorDueDate" LONGDATE CS_LONGDATE, "DsmDueDate" LONGDATE CS_LONGDATE, "NorDueDate" LONGDATE CS_LONGDATE, "Interval" SMALLINT CS_INT, "Multiple" DECIMAL(21,6) CS_FIXED, "MinORdrQty" DECIMAL(21,6) CS_FIXED, "LeadTime" INTEGER CS_INT, "prcrmntMtd" NVARCHAR(1) DEFAULT 'B', "ToleranDay" INTEGER CS_INT, "CompoWH" NVARCHAR(1) DEFAULT 'B', PRIMARY KEY ("AbsEntry", "ItemCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "MSN4_ItemCode" ON "TEST_AP"."MSN4" ( "ItemCode" ASC )